#!/usr/bin/env python3
"""Install the Kolmari country-page template into this repo.

Run from the root of your Kolmari checkout, the folder containing package.json:

    python3 install-Kolmari-template.py

Writes 26 files under src/. Overwrites exactly one existing file,
src/app/(app)/(workspace)/nextinations/page.tsx, and backs it up first.
Nothing else in your repo is touched.
"""
import base64, json, os, shutil, sys

PAYLOAD = ""

OVERWRITES = "src/app/(app)/(workspace)/nextinations/page.tsx"

def main():
    if not os.path.exists("package.json"):
        sys.exit("Run this from your Kolmari repo root, the folder with package.json in it.")
    if not os.path.isdir("src"):
        sys.exit("No src/ directory here. Are you in the right folder?")

    files = json.loads(base64.b64decode(PAYLOAD))
    written, skipped = [], []

    if os.path.exists(OVERWRITES):
        shutil.copy2(OVERWRITES, OVERWRITES + ".backup")
        print("backed up  " + OVERWRITES + ".backup")

    for path, b64 in files.items():
        if path in ("README.md", "SWITCH.diff"):
            out = "Kolmari-template-" + path
        else:
            out = path
        if os.path.exists(out) and out != OVERWRITES and not out.startswith("Kolmari-template-"):
            skipped.append(out)
            continue
        os.makedirs(os.path.dirname(out) or ".", exist_ok=True)
        with open(out, "wb") as f:
            f.write(base64.b64decode(b64))
        written.append(out)

    print()
    print("wrote %d files" % len(written))
    for p in sorted(written):
        print("   " + p)
    if skipped:
        print()
        print("skipped %d existing files (not overwritten):" % len(skipped))
        for p in sorted(skipped):
            print("   " + p)
    print()
    print("Next:")
    print("  1. npm run lint && npm run build      # expect some type errors, fix them")
    print("  2. npm run dev")
    print("  3. open /nextinations/portugal/v2/overview")
    print()
    print("The wizard still lands on the old page until you set:")
    print("  NEXT_PUBLIC_COUNTRY_TEMPLATE=v2")
    print()
    print("To undo: delete src/components/country-template, src/lib/country-template,")
    print("src/styles/country-template.css, the v2 route folder, and restore")
    print(OVERWRITES + " from its .backup file.")

if __name__ == "__main__":
    main()
